import java.util.jar.Attributes;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;
import java.util.jar.Manifest;
import java.util.stream.Stream;

import org.apache.maven.archiver.ManifestConfiguration;
import org.apache.maven.archiver.MavenArchiveConfiguration;
import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugin.MojoFailureException;
import org.apache.maven.project.MavenProject;

public class JarMojo extends AbstractMojo {

    private File outputDirectory;
    private String finalName;
    private String classifier;
    private File classesDirectory;
    private MavenArchiveConfiguration archive;
    private boolean skipIfEmpty = false;
    private boolean forceCreation = false;
    private MavenProject project;

    @Override
    public void execute() throws MojoExecutionException, MojoFailureException {
        if (outputDirectory == null || finalName == null) {
            throw new MojoExecutionException("outputDirectory and finalName are required");
        }
        String name = finalName + (classifier != null && !classifier.isEmpty() ? "-" + classifier : "") + ".jar";
        File jarFile = new File(outputDirectory, name);
        if (skipIfEmpty && (classesDirectory == null || !classesDirectory.isDirectory()
                || isEmpty(classesDirectory.toPath()))) {
            getLog().info("Skipping generation of empty jar " + jarFile);
            return;
        }
        try {
            Files.createDirectories(outputDirectory.toPath());
            createJar(jarFile);
        } catch (IOException e) {
            throw new MojoExecutionException("Error assembling JAR", e);
        }
        getLog().info("Building jar: " + jarFile);
        if (classifier == null || classifier.isEmpty()) {
            if (project != null && project.getArtifact() != null) {
                project.getArtifact().setFile(jarFile);
            }
        }
    }

    private void createJar(File jarFile) throws IOException {
        Manifest manifest = new Manifest();
        Attributes attributes = manifest.getMainAttributes();
        attributes.putValue("Manifest-Version", "1.0");
        attributes.putValue("Created-By", "Apache Maven Jar Plugin");
        if (archive != null) {
            ManifestConfiguration manifestConfig = archive.getManifest();
            if (manifestConfig != null) {
                if (manifestConfig.getMainClass() != null && !manifestConfig.getMainClass().isEmpty()
                        && !manifestConfig.getMainClass().startsWith("${")) {
                    attributes.putValue(Attributes.Name.MAIN_CLASS.toString(), manifestConfig.getMainClass());
                }
                if (manifestConfig.isAddDefaultImplementationEntries()) {
                    if (project != null) {
                        if (project.getGroupId() != null) {
                            attributes.putValue("Implementation-Group-Id" /* placeholder fixed below */ "", "");
                        }
                    }
                }
            }
            if (archive.getManifestEntries() != null) {
                archive.getManifestEntries().forEach(attributes::putValue);
            }
        }
        if (project != null && archive != null && archive.getManifest() != null
                && archive.getManifest().isAddDefaultImplementationEntries()) {
            attributes.putValue("Implementation-Title", safe(project.getArtifactId()));
            attributes.putValue("Implementation-GroupId", safe(project.getGroupId()));
            attributes.putValue("Implementation-ArtifactId", safe(project.getArtifactId()));
            attributes.putValue("Implementation-Version", safe(project.getVersion()));
            attributes.putValue("Implementation-Vendor-Id", safe(project.getGroupId()));
        }
        try (JarOutputStream jarStream = new JarOutputStream(new FileOutputStream(jarFile), manifest)) {
            if (classesDirectory != null && classesDirectory.isDirectory()) {
                Path root = classesDirectory.toPath();
                try (Stream<Path> stream = Files.walk(root)) {
                    stream.filter(Files::isRegularFile).forEach(path -> {
                        String entryName = root.relativize(path).toString().replace(File.separatorChar, '/');
                        try {
                            JarEntry entry = new JarEntry(entryName);
                            entry.setTime(Files.getLastModifiedTime(path).toMillis());
                            jarStream.putNextEntry(entry);
