package com.freshbite.platform.service;

import com.freshbite.platform.dto.ApiResponse;
import com.freshbite.platform.dto.OrderCreateRequest;
import com.freshbite.platform.dto.OrderItemRequest;
import com.freshbite.platform.entity.Dish;
import com.freshbite.platform.entity.Order;
import com.freshbite.platform.entity.OrderItem;
import com.freshbite.platform.mapper.DishMapper;
import com.freshbite.platform.mapper.OrderItemMapper;
import com.freshbite.platform.mapper.OrderMapper;
import org.springframework.stereotype.Service;

import java.security.SecureRandom;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

@Service
public class OrderService {

    public static final String STATUS_PENDING = "PENDING";
    public static final String STATUS_CANCELLED = "CANCELLED";

    private static final char[] ORDER_NO_CHARS =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789".toCharArray();
    private static final DateTimeFormatter ORDER_NO_DATE = DateTimeFormatter.ofPattern("yyyyMMdd");
    private static final SecureRandom RANDOM = new SecureRandom();

    private final OrderMapper orderMapper;
    private final OrderItemMapper orderItemMapper;
    private final DishMapper dishMapper;

    public OrderService(OrderMapper orderMapper, OrderItemMapper orderItemMapper, DishMapper dishMapper) {
        this.orderMapper = orderMapper;
        this.orderItemMapper = orderItemMapper;
        this.dishMapper = dishMapper;
    }

    public ApiResponse<?> submit(Long userId, OrderCreateRequest request) {
        if (request == null || request.getItems() == null || request.getItems().isEmpty()) {
            return ApiResponse.error(400, "订单项不能为空");
        }
        List<OrderItem> items = new ArrayList<>();
        long totalAmount = 0L;
        for (OrderItemRequest itemRequest : request.getItems()) {
            Long dishId = itemRequest == null ? null : itemRequest.getDishId();
            Integer quantity = itemRequest == null ? null : itemRequest.getQuantity();
            if (dishId == null) {
                return ApiResponse.error(400, "菜品不存在: id=" + dishId);
            }
            if (quantity == null || quantity <= 0) {
                return ApiResponse.error(400, "订单项数量必须大于0");
            }
            Dish dish = dishMapper.findById(dishId);
            if (dish == null || !Boolean.TRUE.equals(dish.getAvailable())) {
                return ApiResponse.error(400, "菜品不存在: id=" + dishId);
            }
            long subtotal = (long) quantity * dish.getPrice();
            long newTotal = totalAmount + subtotal;
            if (subtotal < Integer.MIN_VALUE || subtotal > Integer.MAX_VALUE
                    || newTotal < Integer.MIN_VALUE || newTotal > Integer.MAX_VALUE) {
                return ApiResponse.error(400, "订单金额超出可表示范围");
            }
            totalAmount = newTotal;
            OrderItem item = new OrderItem();
            item.setDishId(dishId);
            item.setDishName(dish.getName());
            item.setQuantity(quantity);
            item.setUnitPrice(dish.getPrice());
            item.setSubtotal((int) subtotal);
            items.add(item);
        }

        Order order = new Order();
        order.setOrderNo(generateOrderNo());
        order.setStatus(STATUS_PENDING);
        order.setRemark(request.getRemark());
        order.setUserId(userId);
        order.setTotalAmount((int) totalAmount);
        order.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        orderMapper.insert(order);
        for (OrderItem item : items) {
            item.setOrderId(order.getId());
            orderItemMapper.insert(item);
        }
        order.setItems(items);
        return ApiResponse.success("下单成功", order);
    }

    public ApiResponse<?> list(Long userId, String role) {
        List<Order> orders = "ADMIN".equals(role) ? orderMapper.findAll() : orderMapper.findByUserId(userId);
        return ApiResponse.success(orders);
    }

    public ApiResponse<?> getById(Long userId, String role, Long id) {
        Order order = orderMapper.findById(id);
        if (order == null) {
            return ApiResponse.error(404, "订单不存在");
        }
        if (!"ADMIN".equals(role) && !order.getUserId().equals(userId)) {
            return ApiResponse.error(404, "订单不存在");
        }
        order.setItems(orderItemMapper.findByOrderId(order.getId()));
        return ApiResponse.success(order);
    }

    public ApiResponse<?> cancel(Long userId, String role, Long id) {
        Order order = orderMapper.findById(id);
        if (order == null) {
            return ApiResponse.error(404, "订单不存在");
        }
        if (!"ADMIN".equals(role) && !order.getUserId().equals(userId)) {
            return ApiResponse.error(404, "订单不存在");
        }
        if (!STATUS_PENDING.equals(order.getStatus())) {
            return ApiResponse.error(400, "该订单不可取消");
        }
        orderMapper.updateStatus(order.getId(), STATUS_CANCELLED);
        return ApiResponse.success("取消成功", null);
    }

    private String generateOrderNo() {
        StringBuilder sb = new StringBuilder("ORD-");
        sb.append(ORDER_NO_DATE.format(LocalDate.now())).append('-');
        for (int i = 0; i < 8; i++) {
            sb.append(ORDER_NO_CHARS[RANDOM.nextInt(ORDER_NO_CHARS.length)]);
        }
        return sb.toString();
    }
}

